mapper.select:
        select count(1) as logNum from person_face_match_log  where device_code in
		(select device_no from device_info where area_id = #{areaId} or area_id in ( select t.id from area_model t where find_in_set(#{areaId}, ancestors)  <>  0))
		and received_time >= #{startTime} and received_time <#{endTime} 

       		and result = #{result}

        select count(1) as logNum from person_face_search_log  where device_code in
		(select device_no from device_info where area_id = #{areaId} or area_id in ( select t.id from area_model t where find_in_set(#{areaId}, ancestors)  <>  0))
		and received_time >= #{startTime} and received_time <#{endTime} 

       		and result = #{result}
